#include <Otto.h>
Otto Otto;  //This is Otto!
#define TRIG_PIN 8
#define ECHO_PIN 9
#define LeftLeg 2 
#define RightLeg 3
#define LeftFoot 4 
#define RightFoot 5 
#define Buzzer  13 


void setup(){

  pinMode(TRIG_PIN, OUTPUT);
  pinMode(ECHO_PIN, INPUT);
  randomSeed(analogRead(A5));    // Seed the random number generator
  Otto.init(LeftLeg, RightLeg, LeftFoot, RightFoot, true, Buzzer); //Set the servo pins and Buzzer pin
  Otto.sing(S_connection); //Otto wake up!
  Otto.home();
    delay(50);
  Otto.playGesture(OttoHappy);
}
long getDistance()
{
  digitalWrite(TRIG_PIN, LOW);
  delayMicroseconds(2);

  digitalWrite(TRIG_PIN, HIGH);
  delayMicroseconds(10);

  digitalWrite(TRIG_PIN, LOW);

  long duration = pulseIn(ECHO_PIN, HIGH, 30000);

  long distance = duration * 0.034 / 2;

  return distance;
}


void loop()
{
  long distance = getDistance();

  Serial.print("Distance: ");
  Serial.print(distance);
  Serial.println(" cm");


  // F - Forward
  if(distance > 15)
  {
    Serial.println("F - Forward");
    Otto.walk(2,1000,1);
  }


  // L/R - Avoid obstacle
  else if(distance >= 10 && distance <= 15)
  {
    Serial.println("Obstacle 10-15cm");

    Otto.home();
    delay(100);

    if(random(0,2)==0)
    {
      Serial.println("L - Left");
      Otto.turn(2,1000,1);
    }
    else
    {
      Serial.println("R - Right");
      Otto.turn(2,1000,-1);
    }   

    Otto.home();
    delay(100);
  }


  // B - Backward
  else
  {
    Serial.println("B - Backward");

    Otto.walk(2,1000,-1);

    Otto.home();
    delay(100);

    if(random(0,2)==0)
    {
      Serial.println("L - Escape Left");
      Otto.turn(2,1000,1);
    }
    else
    {
      Serial.println("R - Escape Right");
      Otto.turn(2,1000,-1);
    }

    Otto.home();
    delay(100);
  }
}

