#include "BluetoothSerial.h"

BluetoothSerial SerialBT;

/******************** ULTRASONIC PINS ********************/
#define TRIG_PIN 5
#define ECHO_PIN 18

/******************** L293D MOTOR PINS ********************/

// LEFT MOTOR
#define IN1 19
#define IN2 22

// RIGHT MOTOR
#define IN3 23
#define IN4 21

// ENABLE PINS
#define ENA 26
#define ENB 25

/******************** PWM CHANNELS ********************/
#define CH_LEFT  0
#define CH_RIGHT 1

/******************** SPEEDS ********************/

// OBSTACLE MODE FORWARD SPEED
#define OBSTACLE_FORWARD_SPEED 100

// BLUETOOTH MODE FORWARD SPEED
#define BT_FORWARD_SPEED 255

// TURN SPEED
#define TURN_SPEED 255

#define OBSTACLE_DISTANCE 20

/******************** BLUETOOTH ********************/
char command;

unsigned long lastBTCommand = 0;

bool bluetoothMode = false;

// RETURN TO AUTO MODE AFTER 10 SEC
#define BT_TIMEOUT 10000

bool btRestarted = false;

long distanceCM;

/******************** SETUP ********************/
void setup() {

  Serial.begin(115200);

  // START BLUETOOTH
  SerialBT.begin("ESP32_ROBOT");

  // ULTRASONIC
  pinMode(TRIG_PIN, OUTPUT);
  pinMode(ECHO_PIN, INPUT);

  // MOTOR PINS
  pinMode(IN1, OUTPUT);
  pinMode(IN2, OUTPUT);

  pinMode(IN3, OUTPUT);
  pinMode(IN4, OUTPUT);

  // PWM
  ledcSetup(CH_LEFT, 1000, 8);
  ledcAttachPin(ENA, CH_LEFT);

  ledcSetup(CH_RIGHT, 1000, 8);
  ledcAttachPin(ENB, CH_RIGHT);

  stopMotors();

  Serial.println("Robot Started");
}

/******************** LOOP ********************/
void loop() {

  /******************** BLUETOOTH RECONNECT FIX ********************/
  if (!SerialBT.hasClient() && !btRestarted) {

    btRestarted = true;

    Serial.println("Restarting Bluetooth...");

    SerialBT.end();

    delay(500);

    SerialBT.begin("ESP32_ROBOT");
  }

  if (SerialBT.hasClient()) {

    btRestarted = false;
  }

  /******************** BLUETOOTH CONTROL ********************/
  if (SerialBT.available()) {

    command = SerialBT.read();

    bluetoothMode = true;

    lastBTCommand = millis();

    Serial.print("BT Command: ");
    Serial.println(command);

    stopMotors();

    delay(100);

    // ---------- FORWARD ----------
    if (command == 'F') {

      bluetoothForward();
    }

    // ---------- BACKWARD ----------
    else if (command == 'B') {

      moveBackward();
    }

    // ---------- LEFT ----------
    else if (command == 'L') {

      turnLeft();
    }

    // ---------- RIGHT ----------
    else if (command == 'R') {

      turnRight();
    }

    // ---------- STOP ----------
    else if (command == 'S') {

      stopMotors();
    }
  }

  /******************** RETURN TO AUTO MODE ********************/
  if (bluetoothMode &&
      millis() - lastBTCommand > BT_TIMEOUT) {

    bluetoothMode = false;

    stopMotors();

    Serial.println("Obstacle Avoidance Mode");
  }

  /******************** OBSTACLE AVOIDANCE MODE ********************/
  if (!bluetoothMode) {

    obstacleAvoidance();
  }
}

/******************** OBSTACLE AVOID ********************/
void obstacleAvoidance() {

  distanceCM = getDistance();

  Serial.print("Distance: ");
  Serial.println(distanceCM);

  // ---------- PATH CLEAR ----------
  if (distanceCM > OBSTACLE_DISTANCE) {

    moveForward();
  }

  // ---------- OBSTACLE ----------
  else {

    stopMotors();

    delay(300);

    // ---------- LEFT ----------
    Serial.println("LEFT");

    turnLeft();

    delay(1000);

    stopMotors();

    delay(200);

    distanceCM = getDistance();

    Serial.print("Left Distance: ");
    Serial.println(distanceCM);

    // ---------- STILL BLOCKED ----------
    if (distanceCM <= OBSTACLE_DISTANCE) {

      Serial.println("RIGHT");

      turnRight();

      delay(2000);

      stopMotors();

      delay(200);
    }
  }
}

/******************** DISTANCE FUNCTION ********************/
long getDistance() {

  digitalWrite(TRIG_PIN, LOW);

  delayMicroseconds(2);

  digitalWrite(TRIG_PIN, HIGH);

  delayMicroseconds(10);

  digitalWrite(TRIG_PIN, LOW);

  long duration = pulseIn(ECHO_PIN, HIGH, 30000);

  if (duration == 0)
    return 999;

  return duration * 0.034 / 2;
}

/******************** AUTO MODE FORWARD ********************/
void moveForward() {

  digitalWrite(IN1, HIGH);
  digitalWrite(IN2, LOW);

  digitalWrite(IN3, LOW);
  digitalWrite(IN4, HIGH);

  // OBSTACLE MODE SPEED
  ledcWrite(CH_LEFT, OBSTACLE_FORWARD_SPEED);
  ledcWrite(CH_RIGHT, OBSTACLE_FORWARD_SPEED);
}

/******************** BLUETOOTH FORWARD ********************/
void bluetoothForward() {

  digitalWrite(IN1, HIGH);
  digitalWrite(IN2, LOW);

  digitalWrite(IN3, LOW);
  digitalWrite(IN4, HIGH);

  // BLUETOOTH SPEED
  ledcWrite(CH_LEFT, BT_FORWARD_SPEED);
  ledcWrite(CH_RIGHT, BT_FORWARD_SPEED);
}

/******************** BACKWARD ********************/
void moveBackward() {

  digitalWrite(IN1, LOW);
  digitalWrite(IN2, HIGH);

  digitalWrite(IN3, HIGH);
  digitalWrite(IN4, LOW);

  ledcWrite(CH_LEFT, BT_FORWARD_SPEED);
  ledcWrite(CH_RIGHT, BT_FORWARD_SPEED);
}

/******************** LEFT ********************/
void turnLeft() {

  digitalWrite(IN1, LOW);
  digitalWrite(IN2, HIGH);

  digitalWrite(IN3, LOW);
  digitalWrite(IN4, HIGH);

  ledcWrite(CH_LEFT, TURN_SPEED);
  ledcWrite(CH_RIGHT, TURN_SPEED);
}

/******************** RIGHT ********************/
void turnRight() {

  digitalWrite(IN1, HIGH);
  digitalWrite(IN2, LOW);

  digitalWrite(IN3, HIGH);
  digitalWrite(IN4, LOW);

  ledcWrite(CH_LEFT, TURN_SPEED);
  ledcWrite(CH_RIGHT, TURN_SPEED);
}

/******************** STOP ********************/
void stopMotors() {

  ledcWrite(CH_LEFT, 0);
  ledcWrite(CH_RIGHT, 0);

  digitalWrite(IN1, LOW);
  digitalWrite(IN2, LOW);

  digitalWrite(IN3, LOW);
  digitalWrite(IN4, LOW);
}

